The website does not implement responsive behavior to show desktop navigation links and hide the mobile "Menu" button on wide viewports (R15, R13, R14). The CSS currently hides the desktop nav ('.nav-desktop { display: none; }') and never shows it on larger screens, and the menu button is always visible. Add appropriate CSS media queries (e.g., @media (min-width: 768px) { .nav-desktop { display: flex; } .menu-toggle { display: none; } }) to satisfy the requirement that the header navigation collapses only on phones and works without horizontal scrolling on desktop.
Proven by this test, which fails on the current code:
/** @jest-environment node */
import * as fs from 'fs';
import * as path from 'path';

describe('Responsive navigation CSS', () => {
  test('REPRO: Desktop navigation should be visible on wide viewports and the menu button hidden', () => {
    const cssPath = path.resolve(__dirname, '../../src/styles/global.css');
    const css = fs.readFileSync(cssPath, 'utf8');

    // Ensure the CSS includes a media query for min-width: 768px
    const mediaQueryRegex = /@media\s*\(min-width:\s*768px\)[\s\S]*?\{[\s\S]*?\}/;
    expect(mediaQueryRegex.test(css)).toBe(true);

    // Within that media query, .nav-desktop should be set to display: flex;
    const navDesktopRegex = /@media\s*\(min-width:\s*768px[\s\S]*?\{[\s\S]*?.nav-desktop\s*\{[^}]*display:\s*flex[^}]*\}/;
    expect(navDesktopRegex.test(css)).toBe(true);

    // Within that media query, .menu-toggle should be set to display: none;
    const menuToggleRegex = /@media\s*\(min-width:\s*768px[\s\S]*?\{[\s\S]*?.menu-toggle\s*\{[^}]*display:\s*none[^}]*\}/;
    expect(menuToggleRegex.test(css)).toBe(true);
  });
});
